//! Entry point (`src/main.rs`) for native Slint projects.

/// Generates the `src/main.rs` source content for a Slint application.
pub fn main_rs(form_name: &str, _form_type: &str) -> String {
    format!(
        "// Generated by CrawRAD - do not edit this file directly.\n\
         //\n\
         // Slint application entry point.\n\
         \n\
         #![cfg_attr(not(debug_assertions), windows_subsystem = \"windows\")]\n\
         \n\
         mod {form_name};\n\
         #[path = \"{form_name}.designer.rs\"]\n\
         pub mod {form_name}_designer;\n\
         \n\
         fn main() {{\n\
         \x20   {form_name}_designer::app_main();\n\
         }}\n"
    )
}
